import { prisma } from "@/lib/db";
import { Prisma } from "@prisma/client";
import type { FuelBill } from "@prisma/client";

export type { FuelBill };

// ---- key helpers (grouping identical to the original substr() date logic) ----
export function dateKey(b: Pick<FuelBill, "billDate" | "createdAt">): string {
  return (b.billDate ?? b.createdAt.toISOString().slice(0, 10)).slice(0, 10);
}
export function monthKey(b: Pick<FuelBill, "billDate" | "createdAt">): string {
  return dateKey(b).slice(0, 7);
}
export function employeeKey(b: Pick<FuelBill, "employeeName" | "lineUserId">): string {
  return b.employeeName || b.lineUserId;
}

export interface NewBill {
  lineUserId: string;
  employeeName?: string | null;
  imageUrl?: string | null;
  imageHash?: string | null;
  receiptNo?: string | null;
  station?: string | null;
  billDate?: string | null;
  billTime?: string | null;
  fuelType?: string | null;
  liters?: number | null;
  pricePerLiter?: number | null;
  total?: number | null;
  plate?: string | null;
  status?: string;
  suspectReasons?: string | null;
}

export function insertBill(b: NewBill) {
  return prisma.fuelBill.create({ data: { ...b, status: b.status ?? "ok" } });
}

export function findByHash(hash?: string | null) {
  if (!hash) return Promise.resolve(null);
  return prisma.fuelBill.findFirst({ where: { imageHash: hash } });
}

export function findByReceiptNo(receiptNo?: string | null) {
  if (!receiptNo) return Promise.resolve(null);
  return prisma.fuelBill.findFirst({ where: { receiptNo } });
}

export function findDuplicateBill(b: {
  station?: string | null;
  billDate?: string | null;
  billTime?: string | null;
  total?: number | null;
}) {
  if (b.station == null || b.billDate == null || b.total == null) return Promise.resolve(null);
  return prisma.fuelBill.findFirst({
    where: {
      station: b.station,
      billDate: b.billDate,
      total: b.total,
      ...(b.billTime != null ? { billTime: b.billTime } : {}),
    },
  });
}

export function lastBillOf(lineUserId: string) {
  // The chronologically previous refuel (by receipt datetime), not just the
  // most recently inserted row — bills arrive out of order via LINE.
  return prisma.fuelBill.findFirst({
    where: { lineUserId },
    orderBy: [{ billDate: "desc" }, { billTime: "desc" }, { id: "desc" }],
  });
}

export function billById(id: number) {
  return prisma.fuelBill.findUnique({ where: { id } });
}

export async function billsInMonth(ym: string): Promise<FuelBill[]> {
  // Push the month filter into the DB: billDate starts with "YYYY-MM", or (no
  // billDate) createdAt falls within the month.
  const start = new Date(`${ym}-01T00:00:00.000Z`);
  const end = new Date(Date.UTC(start.getUTCFullYear(), start.getUTCMonth() + 1, 1));
  return prisma.fuelBill.findMany({
    where: {
      OR: [
        { billDate: { startsWith: ym } },
        { AND: [{ billDate: null }, { createdAt: { gte: start, lt: end } }] },
      ],
    },
    orderBy: [{ billDate: "asc" }, { billTime: "asc" }, { id: "asc" }],
  });
}

export async function queryBills(
  filters: { from?: string; to?: string; employee?: string; status?: string } = {}
): Promise<FuelBill[]> {
  const { from, to, employee, status } = filters;
  // Push status + employee into the DB; keep the date-range filter in JS because
  // dateKey falls back to createdAt for rows without a billDate.
  const where: Prisma.FuelBillWhereInput = {};
  if (status) where.status = status;
  if (employee) {
    where.OR = [{ employeeName: employee }, { employeeName: null, lineUserId: employee }];
  }
  const rows = await prisma.fuelBill.findMany({
    where,
    orderBy: [{ billDate: "desc" }, { billTime: "desc" }, { id: "desc" }],
  });
  if (!from && !to) return rows;
  return rows.filter((b) => {
    const dk = dateKey(b);
    if (from && dk < from) return false;
    if (to && dk > to) return false;
    return true;
  });
}

export interface MonthlyRow {
  ym: string;
  employee: string;
  count: number;
  liters: number;
  baht: number;
  suspects: number;
}

export async function monthlyByEmployee(): Promise<MonthlyRow[]> {
  const all = await prisma.fuelBill.findMany();
  const map = new Map<string, MonthlyRow>();
  for (const b of all) {
    const ym = monthKey(b);
    const employee = employeeKey(b);
    const key = `${ym}�${employee}`;
    const row = map.get(key) ?? { ym, employee, count: 0, liters: 0, baht: 0, suspects: 0 };
    row.count++;
    row.liters += Number(b.liters ?? 0);
    row.baht += Number(b.total ?? 0);
    if (b.status === "suspect") row.suspects++;
    map.set(key, row);
  }
  return [...map.values()].sort((a, z) => a.ym.localeCompare(z.ym) || a.employee.localeCompare(z.employee));
}

export async function distinctEmployees(): Promise<string[]> {
  const rows = await prisma.fuelBill.findMany({
    distinct: ["employeeName", "lineUserId"],
    select: { employeeName: true, lineUserId: true },
  });
  return [...new Set(rows.map(employeeKey))].sort();
}
